import{_ as l,o as t,c as n,j as e,a as o}from"./chunks/framework.DdpBa4_E.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/05-1-解密亲密关系行为.md","filePath":"books/attached/05-1-解密亲密关系行为.md","lastUpdated":1794316978000}'),r={name:"books/attached/05-1-解密亲密关系行为.md"};function s(_,a,d,c,i,p){return t(),n("div",null,[...a[0]||(a[0]=[e("h2",{id:"_1-解密亲密关系行为",tabindex:"-1"},[o("1 解密亲密关系行为 "),e("a",{class:"header-anchor",href:"#_1-解密亲密关系行为","aria-label":'Permalink to "1 解密亲密关系行为"'},"​")],-1),e("ul",null,[e("li",null,[e("p",null,"跟这个家伙才约会了两个月，我已经令自己陷入了一种悲哀的担忧中，我担心他觉得我不够诱人，甚至还因为他是否会给我打电话而万分困扰！我深深地知道，我会再一次将那些对自己不够完美的恐惧感，统统变成一种自证预言[1] (self-fulfilling prophecy），同时也将会摧毁这一段关系！")]),e("li",null,[e("p",null,"我到底怎么了？其实我十分聪明、一表人才而且事业有成，这样看来生活似乎十分完满。我曾与一些无可挑剔的女孩约会过，然而过不了几个星期，就会不可避免地失去兴致，并且开始深深地感觉受到束缚。找一个可以和睦相处的人，对我来说本不该如此困难。")]),e("li",null,[e("p",null,"我和丈夫结婚多年，却已经陷入了全然的孤独。他绝非一个愿意表达自己的情感，或是探讨我们之间关系的人，事情从此变得越来越糟。几乎每个工作日晚上，他都熬夜加班，而到了周末，他就要么跟朋友打高尔夫，要么盯着电视上的体育频道。反正没什么事情能让我们和谐共处，或许我一个人待着还更好些！")])],-1),e("p",null,"上述的这些问题都有着很强的杀伤力，可以直击人生的最深处，而且迄今也没有什么万全的解释和解决方法。这些案例看上去都是因人而异的，每个案例都溯源于无限种可能的缘由。想要解密它们，就需要对所有涉及其中的人进行深入的了解。不论人们的过去经历，早先关系还是性格类型，都在一定程度上与现在的情感问题有所关联。这是我们作为心理健康领域的临床从业者所一贯深信的共识。至少在我们新发现一种对这三个问题中描述的症结，乃至更多的问题都能提供直截了当的解释之前，我们都得如此。而这种新发现的来历，以及其带来的结果，也正是这本书的所述。",-1)])])}const h=l(r,[["render",s]]);export{f as __pageData,h as default};
